3	const readStdin = async (): Promise<string> => {
4	  process.stdin.setEncoding("utf8");
5	  let text = "";
6	  for await (const chunk of process.stdin) {
7	    text += chunk;
8	  }
9	  return text;
10	};
11	
12	const reportScenarioResults = async (): Promise<void> => {
13	  const scenario = JSON.parse(await readStdin()) as Scenario;
14	  process.stdout.write(JSON.stringify(runScenario(scenario)));
15	};
16	
17	/** Callers get the description of what went wrong, not the stack trace that led there. */
18	const description = (error: unknown): string =>
19	  error instanceof Error ? error.message : String(error);
20	
21	const FAILURE = 1;
22	
23	try {
24	  await reportScenarioResults();
25	} catch (error) {
26	  process.stderr.write(`${description(error)}\n`);
27	  process.exit(FAILURE);
28	}
